/**
 * Get the organization memberships (name + role) for a user.
 * Used for account-level features like \"Download my data\".
 */
export const getOrganizationMembershipsForUser = reactCache(
  async (userId: string): Promise<{ name: string; role: string }[]> => {
    validateInputs([userId, ZId]);

    try {
      const organizationIds = await lookupAuthorizedOrganizationIds({ type: \"user\", id: userId });
      if (organizationIds.length === 0) return [];

      const memberships = await prisma.membership.findMany({
        where: {
          userId,
          organizationId: { in: organizationIds },
        },
        select: {
          organization: {
            select: {
              name: true,
            },
          },
          role: true,
        },
      });

      return memberships.map((m) => ({
        name: m.organization.name,
        role: m.role,
      }));
    } catch (error) {
      if (error instanceof Prisma.PrismaClientKnownRequestError) {
        throw new DatabaseError(error.message);
      }
      throw error;
    }
  }
);
