"use client";

import { useTranslation } from "react-i18next";
import { TUserNotificationSettings } from "@formbricks/types/user";
import { Button } from "@/modules/ui/components/button";

interface DownloadMyDataProps {
  userName: string;
  userEmail: string;
  userLocale: string;
  notificationSettings: TUserNotificationSettings;
  organizationMemberships: { name: string; role: string }[];
}

export const DownloadMyData = ({
  userName,
  userEmail,
  userLocale,
  notificationSettings,
  organizationMemberships,
}: Readonly<DownloadMyDataProps>) => {
  const { t } = useTranslation();

  const handleDownload = () => {
    const data = {
      name: userName,
      email: userEmail,
      locale: userLocale,
      notificationSettings,
      organizationMemberships: organizationMemberships.map((org) => ({
        organizationName: org.name,
        role: org.role,
      })),
    };

    const jsonString = JSON.stringify(data, null, 2);
    const blob = new Blob([jsonString], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = "formbricks-account-data.json";
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  return (
    <div>
      <p className="text-sm text-slate-700">
        {t("workspace.settings.profile.download_my_data_description")}
      </p>
      <Button className="mt-4" variant="secondary" size="sm" onClick={handleDownload}>
        {t("workspace.settings.profile.download_my_data")}
      </Button>
    </div>
  );
};

/**
 * Get the organization memberships (name + role) for a user.
 * Used for account-level features like "Download my data".
 */
export const getOrganizationMembershipsForUser = reactCache(
  async (userId: string): Promise<{ name: string; role: string }[]> => {
    validateInputs([userId, ZId]);

    try {
      const organizationIds = await lookupAuthorizedOrganizationIds({ type: "user", id: userId });
      if (organizationIds.length === 0) return [];

      const memberships = await prisma.membership.findMany({
        where: {
          userId,
          organizationId: { in: organizationIds },
        },
        select: {
          organization: {
            select: {
              name: true,
            },
          },
          role: true,
        },
      });

      return memberships.map((m) => ({
        name: m.organization.name,
        role: m.role,
      }));
    } catch (error) {
      if (error instanceof Prisma.PrismaClientKnownRequestError) {
        throw new DatabaseError(error.message);
      }
      throw error;
    }
  }
);

